import type { PrismaClient } from "@/generated/prisma/client";

type Level = "BEGINNER" | "INTERMEDIATE" | "ADVANCED";
type MaterialType = "COURSE" | "GUIDE" | "CASE" | "WORKSHOP";
type LessonKind = "THEORY" | "PRACTICE";

type LessonDraft = {
  slug: string;
  title: string;
  content: string;
  videoUrl?: string;
  kind?: LessonKind;
  durationMinutes?: number;
};

type ModuleDraft = {
  title: string;
  lessons: LessonDraft[];
};

type MaterialDraft = {
  slug: string;
  title: string;
  description: string;
  type: MaterialType;
  level: Level;
  tag: string;
  coverImage?: string;
  modules: ModuleDraft[];
};

const singleLesson = (title: string, content: string): ModuleDraft[] => [
  { title: "Материал", lessons: [{ slug: "content", title, content }] },
];

